function GachaponSkinBlendRoleNode:RefreshRoleNodeShow(moduleIds)
	local moduleIds = moduleIds
	for i = 1, 3 do
		local item = self["BtnRoleNameNode"..i]
		if item then
			local skinId = moduleIds[i]
			if checkNumber(skinId) > 0 then
				local cardSkinVo = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", skinId)
				if cardSkinVo then
					CfUtils.SetActive(item.gameObject,true)
					---@type CommonBtnRoleNameNode
					local env = CfUtils.GetLuaScr(item, "Game.UI.Common.CommonBtnRoleNameNode")
					if env then
						env:RefreshSelf(skinId, cardSkinVo:GetRare(), nil, true)
					end
				else
					CfUtils.SetActive(item.gameObject,false)
				end
			else
				CfUtils.SetActive(item.gameObject,false)
			end
		end
	end
end

function GachaponSkinBlendRoleNode:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return GachaponSkinBlendRoleNode